using System.Windows;
namespace Ahenk;
public partial class App : Application
{
 void Window_Loaded(object sender,RoutedEventArgs e){if(sender is Window window){window.Icon??=new System.Windows.Media.Imaging.BitmapImage(new Uri("pack://application:,,,/Assets/Lyra.ico"));NativeAppearance.Apply(window);}}
 protected override async void OnStartup(StartupEventArgs e)
 {
  base.OnStartup(e);
  L.Load();
  if(e.Args.Length>=2&&e.Args[0]=="--library-sync-test"){try{await LibrarySyncTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"library-sync-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--startup-smoke-test"){try{await StartupSmokeTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"startup-smoke-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--desktop-players-test"){try{await DesktopPlayersTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"desktop-players-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--endpoint-sharing-test"){try{await EndpointSharingTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"endpoint-sharing-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=3&&e.Args[0]=="--inspect-pcm"){try{await PcmInspection.Run(e.Args[1],e.Args[2]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"inspection-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--localization-test"){try{await LocalizationTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"localization-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--automatic-audio-test"){try{await AutomaticAudioTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"automatic-audio-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--pcm-compatibility-test"){try{await PcmCompatibilityTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"pcm-compatibility-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--exclusive-probe"){try{ExclusiveDiagnostics.Probe(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"exclusive-probe-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--collection-ui-test"){try{await CollectionUiTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"collection-ui-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--fullscreen-test"){try{await FullscreenPlayerTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"fullscreen-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0] is "--artist-photo-test" or "--artist-photo-live-test"){try{await ArtistPhotoTests.Run(e.Args[1],e.Args[0]=="--artist-photo-live-test");Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"artist-photo-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--customization-test"){try{await CustomizationTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"customization-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--visualizer-ui-test"){try{await VisualizerUiTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"visualizer-ui-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--visualizer-streaming-test"){try{await VisualizerStreamingTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"visualizer-streaming-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--upgrade-ui-test"){try{await UpgradeUiTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"upgrade-ui-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--upgrade-test"){try{await UpgradeTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"upgrade-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--player-state-test"){try{await PlayerStateTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"player-state-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--desktop-playback-test"){try{await DesktopPlaybackTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"desktop-playback-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--audio-safety-test"){try{await AudioSafetyTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"audio-safety-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--audio-features-test"){try{await AudioFeatureTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"audio-features-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--lyrics-live-check"){try{await LyricsTests.LiveCheck(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"lyrics-live-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--experience-test"){try{await ExperienceTests.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"experience-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length>=2&&e.Args[0]=="--audio-check"){try{await AudioDiagnostics.Run(e.Args[1]);Shutdown(0);}catch(Exception ex){System.IO.Directory.CreateDirectory(e.Args[1]);System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"audio-error.txt"),ex.ToString());Shutdown(1);}return;}
  if(e.Args.Length >= 2 && e.Args[0] == "--self-test") { try { await SelfTest.Run(e.Args[1]); Shutdown(0); } catch(Exception ex) { System.IO.File.WriteAllText(System.IO.Path.Combine(e.Args[1],"test-error.txt"),ex.ToString()); Shutdown(1); } return; }
  DispatcherUnhandledException += (_,args)=> { MessageBox.Show(args.Exception.Message,"Lyra — hata"); args.Handled=true; };
  if(e.Args.Length>=2&&e.Args[0]=="--startup-benchmark")StartupMetrics.Start(e.Args[1]);
  Themes.Load();var main=new MainWindow();if(StartupMetrics.Enabled){main.Opacity=0;main.ShowInTaskbar=false;}main.Show();
 }
}
